mapper.select:
SELECT * FROM certificates
WHERE tenant_id = #{tenantId}
ORDER BY expiry_date DESC

mapper.insert:
INSERT INTO certificates (
    tenant_id, certificate_name, certificate_type, certificate_number,
    issue_date, expiry_date, issuing_authority, renewal_fee,
    status, attachment_url, notes, created_at, updated_at, created_by, updated_by
) VALUES (
    #{tenantId}, #{certificateName}, #{certificateType}, #{certificateNumber},
    #{issueDate}, #{expiryDate}, #{issuingAuthority}, #{renewalFee},
    #{status}, #{attachmentUrl}, #{notes}, NOW(), NOW(), #{createdBy}, #{updatedBy}
)
